// =====================================================================
//  lab-data.js — MBL 수업허브 실험 도감 데이터  (전역 window.LAB)
//  제작: 해누리중학교 조승재(과학이조선생)   ·   갱신: 2026-07-06
//
//  ▶ 구성
//     [ref] 센서 24종 · 보드 6종 · 2022개정 중학 성취기준 87개 · 단원 23개
//     [g1]  중1 실험 18건   [g2] 중2 실험 16건   [g3] 중3 실험 14건   = 총 48건
//     원자료: 이지메이커 수업사례집 23건(src:'ez') + 서울특별시교육청 2026 교수학습자료집 10건(src:'seoul')
//             (두 자료집에 함께 실린 7쌍은 서울 자료 기준으로 병합하고 altSrc:'ez' 를 남겼습니다)
//             + 교과서 수록표·클래스보드 기초측정·공기압 연수 자료 13건(src:'cb')
//             + 자료집에 같은 실험이 없어 새로 구성한 2건(src:'own')
//     실험마다 srcRef 에 원자료에서의 위치(사례 번호 등)를 적어 두었습니다.
//     ⚠ ez-NN 의 번호는 우리 일련번호이지 사례집 번호가 아닙니다. 사례집을 찾을 때는 srcRef 를 보세요.
//     실험 1건마다 pool(합치기 값어치)과 analysis(분석 레시피)가 함께 들어 있습니다.
//
//  ▶ 쓰는 법
//     <script src="lab-data.js"></script>
//     LAB.experiments            // 실험 48건 배열
//     LAB.byId('sm-01')          // 실험 1건
//     LAB.byGrade(1)             // 중1 실험만
//     LAB.byUnit('열')           // 단원별
//     LAB.bySensor('temp')       // 그 센서를 쓰는 실험
//     LAB.byStd('9과03-03')      // 성취기준별
//     LAB.sensorName('co2')      // '이산화탄소'
//     LAB.stdText('9과03-03')    // 성취기준 원문
//     LAB.unitList(2)            // 중2 단원 목록
//     LAB.sensorCost('sm-01','ezw')  // 그 실험 1세트 센서 값(원). 미취급이면 null
//     LAB.search('광합성')       // 제목·단원·센서 이름으로 찾기
//
//  ▶ 합치기·분석 (실험 객체의 pool · analysis)
//     LAB.poolFit('sm-05')       // 1~3. 반 전체 자료를 합쳤을 때의 값어치
//     LAB.byPool(3)              // 합치면 아주 유리한 실험만
//     LAB.analysisOf('sm-05')    // 그 실험의 분석 레시피(goal·steps·verdict)
//     LAB.meta.counts.pool3/pool2/pool1
//
//  ▶ 업체별 (ez 이지메이커 · sc 사이언스큐브)
//     LAB.VENDORS                    // [{key,name,sw}]  sw = ezon.ai / 사이언스#
//     LAB.sensorHas('force','ez')    // 그 업체가 그 센서를 파는가 → false
//     LAB.vendorOk(exp,'sc')         // 쓰이는 센서가 전부 있어야 true
//     LAB.stepsFor(exp,'ez')         // 그 업체 절차(stepsBy). 없으면 exp.steps 폴백
//     LAB.prepFor(exp,'sc')          // exp.prep + setupBy[vendor]
//     LAB.byVendor('ez')             // 그 업체로 가능한 실험만
//     실험 객체의 stepsBy·setupBy 는 업체를 고른 경우에만 쓰고, 기존 steps·prep 은 기본값입니다.
//
//  ▶ area 어휘 주의
//     experiments[].area = physics | chem | bio | earth   (실험 영역)
//     units[].area       = energy | matter | life | earth | society  (별책9 영역)
//     대응: energy→physics, matter→chem, life→bio, earth→earth (society 는 대응 없음)
//
//  ▶ analysis 레시피를 고칠 때 꼭 알아야 할 것 (판정 엔진은 index.html 의 runAnalysis)
//     · verdict 의 when 은 '이름 비교식 숫자' 한 줄뿐입니다(and·or 없음). 위에서부터 처음 맞는 것이 쓰입니다.
//     · 쓸 수 있는 이름: r2 · r2Min · slope · intercept · mean · range · delta · n
//     · ★ r2 · slope · intercept 는 '마지막 fit' 의 값만 남습니다. fit 이 여러 개인 실험에서
//       'r2 >= 0.9' 라고 쓰면 마지막 계열 하나만 깨끗해도 전부 깨끗하다고 판정합니다.
//       계열이 여럿이면 r2Min(그 실험에 나온 모든 fit 의 R² 중 최솟값)을 쓰세요.
//       특정 fit 의 값을 보고 싶으면 그 fit 을 steps 의 맨 뒤로 옮기세요.
//     · ★ range 는 max−min 이라 늘 0 이상이라 방향이 없습니다. '올랐다/내려갔다/더 크다' 처럼
//       방향을 말하는 결론에는 반드시 부호가 있는 delta(=마지막 값−첫 값)나 slope 를 함께 쓰세요.
//       (range 는 '변화 폭이 충분한가' 를 재는 용도로만.)
//     · mean · range · delta · n 은 마지막 stat(또는 fit) 의 값입니다.
//
//  ▶ 이 파일은 lab-part-ref.js / g1 / g2 / g3 을 이어 붙여 만들었던 결과물이지만,
//     ★ 지금은 lab-data.js 가 원본입니다. 파트 파일(lab-part-*.js · vendor-steps-*.js)은
//     실험 38건 시점의 낡은 사본이라 cb-01~cb-10 과 ez-06·ez-13 수정, 그 뒤의 판정 레시피 손질이
//     들어 있지 않습니다. 다시 합치면 그 내용이 조용히 사라집니다.
//     자료를 고칠 때는 이 파일(lab-data.js)을 직접 고치십시오. 어떤 HTML 도 파트 파일을 읽지 않습니다.
// =====================================================================


